begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,auth;
select no_plan();
\ir fixtures/final-result-readiness-setup.sql
create temporary table activation_fixture(expiry timestamptz,approval jsonb,publication jsonb);
insert into activation_fixture(expiry) values(clock_timestamp()+interval '30 minutes');
grant select,update on activation_fixture to authenticated;
create function pg_temp.approve(p_id uuid default '87960000-0000-4000-8000-000000000001',p_expected uuid default null,p_verify uuid default '87950000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select api.cmd_final_result_release_approve_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),p_verify,p_id,p_expected,(select expiry from activation_fixture),'synthetic approved selection')
$$;
create function pg_temp.activate(p_key text default 'synthetic-activation',p_verify uuid default '87950000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select api.cmd_final_result_release_activate_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),(approval#>>'{data,approvalId}')::uuid,approval#>>'{data,approvalHash}',p_verify,p_key,repeat('f',64)) from activation_fixture
$$;
create function pg_temp.published_id() returns uuid language sql as $$select (publication#>>'{data,publicationId}')::uuid from activation_fixture$$;
grant execute on function pg_temp.approve(uuid,uuid,uuid),pg_temp.activate(text,uuid),pg_temp.published_id() to authenticated;
select ok(not has_function_privilege('service_role','api.cmd_final_result_release_approve_v2(uuid,text,uuid,uuid,uuid,timestamptz,text)','execute'),'service verifier cannot approve');
select ok(not has_function_privilege('service_role','api.cmd_final_result_release_activate_v2(uuid,text,uuid,text,uuid,text,text)','execute'),'service verifier cannot activate');
select ok(not has_function_privilege('anon','api.qry_final_result_query_v2(uuid,text,uuid)','execute'),'anonymous caller cannot obtain reader descriptors');
select ok(not has_table_privilege('authenticated','private.final_result_publication_bindings','select'),'browser cannot enumerate publication bindings');
select ok(not has_table_privilege('authenticated','private.final_result_candidate_members','select'),'browser cannot enumerate Candidate members');
select ok(not has_schema_privilege('api_internal_executor','private','create'),'temporary owner CREATE grant restored');
select is((select proowner::regrole::text from pg_proc where oid='private.final_result_source_readable(uuid,text)'::regprocedure),'api_internal_executor','source uses RLS-bound owner');
set local role authenticated;
select throws_ok($q$select pg_temp.approve()$q$,'55000','Fresh final Result readiness is required','approval cannot bypass fresh readiness');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000010','01.00.000')->>'code','published_result_not_available','staged results remain unavailable');
reset role;
set local role service_role;
select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header());
select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',pg_temp.readiness_proofs());
select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001');
-- A fresh later verification is allowed only under the same approved context.
select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header('{"verificationId":"87950000-0000-4000-8000-000000000002"}'));
select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000002',pg_temp.readiness_proofs());
select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000002');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000002',true);
select is(pg_temp.approve()->>'code','not_data_product_manager','ordinary reader cannot approve');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
update activation_fixture set approval=pg_temp.approve();
select is((select approval#>>'{data,status}' from activation_fixture),'approved','actor approves exact qualified selection');
select is(pg_temp.approve()#>>'{data,reused}','true','lost approval ACK recovers original approval');
select is(pg_temp.approve('87960000-0000-4000-8000-000000000002')->>'code','expected_approval_conflict','replacement needs exact current approval');
select is(pg_temp.approve('87960000-0000-4000-8000-000000000001',null,'87950000-0000-4000-8000-000000000002')->>'code','approval_identity_conflict','approval ID cannot silently bind another verification');
select is(api.cmd_lca_release_approve('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),clock_timestamp()+interval '1 hour','legacy attempt','{}')->>'code','final_result_versioned_api_required','legacy approval cannot reinterpret v2');
select is(api.get_lca_release_run('87930000-0000-4000-8000-000000000010')->>'code','final_result_versioned_api_required','legacy run DTO cannot masquerade as a four-ZIP release');
update activation_fixture set approval=pg_temp.approve('87960000-0000-4000-8000-000000000002','87960000-0000-4000-8000-000000000001');
select is((select approval#>>'{data,status}' from activation_fixture),'approved','explicit replacement succeeds');
select is(pg_temp.approve()#>>'{data,status}','revoked','old approval retry never resurrects authority');
reset role;
savepoint drift;
set local role service_role;
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000002','87940000-0000-4000-8000-000000000001',repeat('d',64),repeat('c',64),false,'synthetic disable');
reset role;
set local role authenticated;
select throws_ok($q$select pg_temp.activate()$q$,'55000','Final Result verification context is no longer eligible','disabled runtime blocks activation');
rollback to drift;
savepoint permission_drift;
delete from private.roles where user_id='87930000-0000-4000-8000-000000000001';
set local role authenticated;
select is(pg_temp.activate()->>'code','not_data_product_manager','revoked manager cannot activate');
rollback to permission_drift;
set local role authenticated;
update activation_fixture set publication=pg_temp.activate('synthetic-activation','87950000-0000-4000-8000-000000000002');
select is((select publication#>>'{data,status}' from activation_fixture),'current','fresh same-context verification activates');
select is(pg_temp.activate('synthetic-activation','87950000-0000-4000-8000-000000000002')#>>'{data,reused}','true','lost activation ACK recovers exact original publication');
select is(pg_temp.activate('another-key','87950000-0000-4000-8000-000000000002')->>'code','publish_idempotency_conflict','different execution cannot reuse run');
select is(pg_temp.activate()->>'code','publish_idempotency_conflict','different verification cannot rewrite activation evidence');
reset role;
select is((select status from private.lca_release_runs where id='87930000-0000-4000-8000-000000000010'),'published','activation does not fake independent post-publication observation');
select is((select status from private.lca_release_approvals where id='87960000-0000-4000-8000-000000000002'),'consumed','approval consumed atomically');
select is((select count(*) from private.lca_release_publications where is_current),1::bigint,'one current publication');
select throws_ok($q$delete from private.final_result_publication_bindings$q$,'55000','Result query evidence is immutable','activation binding immutable');
set local role authenticated;
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000002',true);
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000012','01.00.000')#>>'{data,relationKind}','derived','explicit published Derived C readable without access to parents A/B');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000010','01.00.000')#>>'{data,scope,publicationId}',pg_temp.published_id()::text,'reader immediately uses activated publication scope');
select ok(not ((api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000012','01.00.000')->'data') ?| array['sources','contentHash','candidateHash']),'public descriptor exposes no ancestry or private catalog');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000011','01.00.000')->>'code','published_result_not_available','file-contained unselected Result remains unavailable');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000012','01.00.001')->>'code','published_result_not_available','no nearest-version fallback');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000012','01.00.000','87960000-0000-4000-8000-000000000099')->>'code','published_result_not_available','wrong publication never falls back to current');
select is(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.000')->>'code','source_not_available','parent source cannot be disclosed by published Derived C');
select is(api.qry_final_result_download_v2(pg_temp.published_id(),'tidas')->>'code','result_package_not_available','prebuilt ZIP cannot expose an unselected Result');
reset role;
-- Synthetic fixture only: suppress unrelated extraction/network writers.
set local session_replication_role=replica;
insert into public.processes(id,version,json,user_id,state_code) values('87920000-0000-4000-8000-000000000030','01.00.000','{}','87930000-0000-4000-8000-000000000002',0);
set local session_replication_role=origin;
set local role authenticated;
select is(jsonb_array_length(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.000')#>'{data,results}'),1,'readable source resolves only direct selected Results');
select is(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.000')#>>'{data,results,0,uuid}','87920000-0000-4000-8000-000000000010','Derived children are never implicit source aliases');
select is(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.001')->>'code','source_not_available','source lookup uses exact visible version');
reset role;
create policy final_result_source_canary on public.processes as restrictive for select to api_internal_executor using(false);
select is(private.final_result_source_readable('87920000-0000-4000-8000-000000000030','01.00.000'),false,'direct RLS helper honors canary');
set local role authenticated;
select is(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.000')->>'code','source_not_available','future restrictive source policy is honored');
reset role;
drop policy final_result_source_canary on public.processes;
select is(private.final_result_candidate_support_readable(pg_temp.candidate_fixture()#>>'{receipt,candidateSha256}'),false,'missing support row denies complete ZIP even under internal reader');
-- Synthetic fixture only: suppress unrelated extraction/network writers.
set local session_replication_role=replica;
insert into public.flows(id,version,json,user_id,state_code) values('87920000-0000-4000-8000-000000000050','01.00.000','{}','87930000-0000-4000-8000-000000000001',0);
set local session_replication_role=origin;
select is(private.final_result_candidate_support_readable(pg_temp.candidate_fixture()#>>'{receipt,candidateSha256}'),false,'existing private support row also denies ZIP');
-- Synthetic fixture only: suppress unrelated extraction/network writers.
set local session_replication_role=replica;
update public.flows set state_code=100 where id='87920000-0000-4000-8000-000000000050';
set local session_replication_role=origin;
select is(private.final_result_candidate_support_readable(pg_temp.candidate_fixture()#>>'{receipt,candidateSha256}'),true,'public support closure passes RLS');
create policy final_result_support_canary on public.flows as restrictive for select to api_internal_executor using(false);
select is(private.final_result_candidate_support_readable(pg_temp.candidate_fixture()#>>'{receipt,candidateSha256}'),false,'future restrictive support policy is honored');
drop policy final_result_support_canary on public.flows;
set local role authenticated;
select is(api.qry_final_result_download_v2(pg_temp.published_id(),'tidas')->>'code','result_package_not_available','readable support does not bypass missing selected root');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
select is(api.cmd_lca_release_unpublish(pg_temp.published_id(),'synthetic withdrawal')->>'ok','true','shared release authority can withdraw v2');
select is(api.qry_final_result_query_v2('87920000-0000-4000-8000-000000000010','01.00.000')->>'code','published_result_not_available','withdrawal removes public query capability');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000002',true);
select is(api.qry_source_final_results_v2('87920000-0000-4000-8000-000000000030','01.00.000',null,100,pg_temp.published_id())->>'code','publication_changed','withdrawal invalidates publication-bound source pagination');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
select is(pg_temp.activate('synthetic-activation','87950000-0000-4000-8000-000000000002')#>>'{data,isCurrent}','false','historical retry never revives withdrawn publication');
reset role;
select * from finish();
rollback;
